css:
/* ==== INTERFACE ====
方向：明亮课堂纸页上的手绘笔记语言；深墨文字、铅笔式双线、黄色荧光笔与绿色批注形成清楚层级，不规定页面布局。
token --bg：纸页底色。
token --text：正文墨色。
token --font-sans：中英混排正文与控件字体。
token --muted：次要文字。
token --focus：键盘焦点色。
token --accent：增长与重点黄色。
token --accent-ink：黄色重点上的深色文字。
token --growth：增长曲线与当前增长值绿色。
token --line：手绘轮廓色。
token --fs-h1/--fs-h2/--fs-lead/--fs-body/--fs-sec/--fs-label/--fs-tick：投影字阶。
class .nt-title：中英标题；英文优先 Caveat 600，中文承接 LXGW WenKai 500。
class .nt-body：中英正文；英文优先 Inter 400，中文承接 LXGW WenKai 400。
class .nt-number：数字、百分比、金额和短标签；Inter 600，使用表格数字。
class .nt-lead：课堂导语。
class .nt-kicker：短章节标签。
class .nt-highlight：行内荧光笔重点。
class .nt-note：带手绘边线的补充说明。
class .nt-formula：公式外围的原生 CSS 纸条材质；公式引擎内部排版保持独立。
class .nt-growth-chart：挂在 SVG 上，提供清晰的轴线、曲线、点和文字样式；实际数据几何仍由 Builder 决定。
class .nt-controls：课堂交互控件容器；按钮使用 .nt-button，输入使用 .nt-input。
variant opening：开篇页的暖白纸面与更醒目的黄色手绘光斑，适合中英总标题；不改变内容几何。
默认：不设 data-variant；无图，以纸纤维渐变和铅笔线材质构成背景。
品牌：无。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-1.ttf");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-caveat";
  src: url("fonts/library/caveat/face-0.ttf");
  font-weight: 400 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

:root {
  --bg: #fffdf4;
  --text: #202820;
  --muted: #59645a;
  --focus: #166b50;
  --accent: #f3c83f;
  --accent-ink: #222516;
  --growth: #26875f;
  --line: #29332d;
  --paper-line: rgba(43, 57, 47, 0.075);
  --soft-yellow: #fff1a8;
  --soft-green: #dff2d7;
  --soft-blue: #dcecf5;
  --danger: #b33c32;
  --font-sans: "NTF-inter", "NTF-lxgw-wenkai", sans-serif;
  --font-title: "NTF-caveat", "NTF-lxgw-wenkai", cursive;
  --font-number: "NTF-inter", sans-serif;
  --fs-h1: 76px;
  --fs-h2: 48px;
  --fs-lead: 30px;
  --fs-body: 24px;
  --fs-sec: 20px;
  --fs-label: 17px;
  --fs-tick: 14px;
  --space-1: 8px;
  --space-2: 14px;
  --space-3: 22px;
  --space-4: 34px;
  --space-5: 52px;
  --space-6: 76px;
  color-scheme: light;
  font-family: var(--font-sans);
  color: var(--text);
  background: var(--bg);
}

html[data-variant="opening"] {
  --bg: #fffaf0;
  --text: #1f2922;
  --muted: #566158;
  --focus: #0f7050;
  --accent: #ffd84f;
  --accent-ink: #242716;
  --growth: #2b8a5e;
  --line: #253029;
  --paper-line: rgba(62, 57, 39, 0.07);
  --soft-yellow: #ffeca0;
  --soft-green: #dcedd3;
  --soft-blue: #d9ebf1;
}

#stage {
  color: var(--text);
  font-family: var(--font-sans);
  background-color: var(--bg);
  background-image:
    linear-gradient(7deg, transparent 0 49.72%, var(--paper-line) 49.8% 50%, transparent 50.08% 100%),
    linear-gradient(93deg, transparent 0 49.78%, rgba(65, 77, 68, 0.035) 49.86% 50.02%, transparent 50.1% 100%),
    radial-gradient(circle at 14% 20%, rgba(243, 200, 63, 0.09) 0 8%, transparent 8.2%),
    radial-gradient(circle at 88% 82%, rgba(38, 135, 95, 0.055) 0 9%, transparent 9.2%);
  background-size: 250px 190px, 310px 230px, 100% 100%, 100% 100%;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

html[data-variant="opening"] #stage {
  background-image:
    radial-gradient(ellipse at 68% 30%, rgba(255, 216, 79, 0.3) 0 10%, rgba(255, 216, 79, 0.13) 10.4% 17%, transparent 17.4%),
    linear-gradient(6deg, transparent 0 49.72%, var(--paper-line) 49.8% 50%, transparent 50.08% 100%),
    linear-gradient(94deg, transparent 0 49.8%, rgba(67, 76, 66, 0.03) 49.88% 50.02%, transparent 50.1% 100%);
  background-size: 100% 100%, 270px 205px, 330px 250px;
}

.nt-title {
  margin: 0;
  color: var(--text);
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 600;
  font-style: normal;
  line-height: 1.08;
  letter-spacing: 0.005em;
  text-wrap: balance;
  text-shadow: 0.7px 0.7px 0 rgba(32, 40, 32, 0.16);
}

.nt-title[lang="zh"],
.nt-title :lang(zh) {
  font-family: "NTF-lxgw-wenkai", sans-serif;
  font-weight: 500;
  letter-spacing: 0.035em;
}

.nt-title[lang="en"],
.nt-title :lang(en) {
  font-family: "NTF-caveat", "NTF-lxgw-wenkai", cursive;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.nt-title.nt-title--secondary {
  font-size: var(--fs-h2);
  line-height: 1.16;
}

.nt-body {
  margin-block: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 400;
  line-height: 1.72;
  letter-spacing: 0.008em;
  hanging-punctuation: first last;
}

.nt-body[lang="zh"],
.nt-body :lang(zh) {
  font-family: "NTF-inter", "NTF-lxgw-wenkai", sans-serif;
  letter-spacing: 0.018em;
}

.nt-body strong,
.nt-body b {
  font-weight: 650;
  color: #17261d;
}

.nt-body em,
.nt-body i {
  font-family: "NTF-inter", "NTF-lxgw-wenkai", sans-serif;
  font-style: italic;
}

.nt-lead {
  margin-block: 0;
  color: #344239;
  font-family: var(--font-sans);
  font-size: var(--fs-lead);
  font-weight: 400;
  line-height: 1.55;
  letter-spacing: 0.006em;
  text-wrap: pretty;
}

.nt-number {
  color: inherit;
  font-family: var(--font-number);
  font-size: 1em;
  font-weight: 650;
  font-style: normal;
  line-height: 1;
  letter-spacing: -0.018em;
  font-variant-numeric: tabular-nums lining-nums;
  font-feature-settings: "tnum" 1, "lnum" 1, "zero" 1;
  white-space: nowrap;
}

.nt-number--hero {
  color: var(--growth);
  font-size: clamp(52px, 5.4vw, 104px);
  font-weight: 750;
  letter-spacing: -0.045em;
  text-shadow: 2px 2px 0 rgba(38, 135, 95, 0.13);
}

.nt-kicker {
  display: inline-block;
  color: var(--accent-ink);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.075em;
  text-transform: uppercase;
  padding: 7px 15px 8px;
  background: var(--accent);
  border: 2px solid var(--line);
  border-radius: 48% 52% 46% 54% / 56% 45% 55% 44%;
  box-shadow: 2px 3px 0 rgba(41, 51, 45, 0.18);
  transform: rotate(-0.7deg);
}

.nt-highlight {
  color: inherit;
  padding-inline: 0.12em;
  background-image: linear-gradient(176deg, transparent 0 48%, rgba(243, 200, 63, 0.68) 49% 86%, transparent 87% 100%);
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

.nt-highlight--growth {
  background-image: linear-gradient(178deg, transparent 0 50%, rgba(120, 197, 134, 0.48) 51% 88%, transparent 89% 100%);
}

.nt-note {
  color: #344139;
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  line-height: 1.6;
  padding: 18px 22px;
  background: rgba(255, 255, 255, 0.56);
  border: 2px solid rgba(41, 51, 45, 0.82);
  border-radius: 17px 12px 19px 13px / 12px 18px 13px 19px;
  box-shadow: 3px 4px 0 rgba(41, 51, 45, 0.12), inset 0 0 0 2px rgba(255, 255, 255, 0.55);
}

.nt-note--growth {
  border-color: var(--growth);
  background: rgba(223, 242, 215, 0.68);
}

.nt-formula {
  display: inline-flex;
  align-items: baseline;
  gap: 0.32em;
  min-height: 1.35em;
  color: var(--text);
  font-family: var(--font-number);
  font-size: clamp(28px, 2.6vw, 48px);
  font-weight: 600;
  line-height: 1.3;
  padding: 0.28em 0.48em 0.32em;
  background-color: rgba(255, 255, 255, 0.76);
  background-image: linear-gradient(transparent 72%, rgba(220, 236, 245, 0.72) 72% 76%, transparent 76%);
  border: 2px solid var(--line);
  border-radius: 9px 13px 8px 12px / 12px 8px 13px 9px;
  box-shadow: 3px 4px 0 rgba(41, 51, 45, 0.12);
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-formula .nt-number {
  color: var(--growth);
  font-weight: 750;
}

.nt-caption {
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 400;
  line-height: 1.5;
}

.nt-rule {
  height: 4px;
  border: 0;
  margin: 0;
  background: linear-gradient(178deg, transparent 0 20%, var(--line) 24% 52%, transparent 57%), linear-gradient(181deg, transparent 0 54%, rgba(41, 51, 45, 0.48) 58% 72%, transparent 76%);
  opacity: 0.78;
}

.nt-growth-chart {
  color: var(--text);
  font-family: var(--font-number);
  overflow: visible;
}

.nt-growth-chart .nt-axis,
.nt-growth-chart .nt-grid,
.nt-growth-chart .nt-curve,
.nt-growth-chart .nt-point {
  vector-effect: non-scaling-stroke;
}

.nt-growth-chart .nt-axis {
  fill: none;
  stroke: var(--line);
  stroke-width: 2.5;
  stroke-linecap: round;
}

.nt-growth-chart .nt-grid {
  fill: none;
  stroke: rgba(41, 51, 45, 0.18);
  stroke-width: 1.5;
  stroke-dasharray: 7 9;
  stroke-linecap: round;
}

.nt-growth-chart .nt-curve {
  fill: none;
  stroke: var(--growth);
  stroke-width: 6;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(2px 3px 0 rgba(38, 135, 95, 0.14));
}

.nt-growth-chart .nt-point {
  fill: var(--accent);
  stroke: var(--line);
  stroke-width: 2.5;
}

.nt-growth-chart .nt-area {
  fill: rgba(120, 197, 134, 0.16);
  stroke: none;
}

.nt-growth-chart .nt-label {
  fill: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
}

.nt-growth-chart .nt-tick {
  fill: var(--muted);
  font-family: var(--font-number);
  font-size: var(--fs-tick);
  font-weight: 500;
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-growth-chart .nt-value {
  fill: var(--growth);
  font-family: var(--font-number);
  font-size: var(--fs-sec);
  font-weight: 750;
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-controls {
  --control-surface: rgba(255, 255, 255, 0.84);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
}

.nt-controls label {
  color: var(--text);
  font-size: var(--fs-label);
  font-weight: 650;
  line-height: 1.4;
}

.nt-button {
  min-height: 48px;
  padding: 10px 20px;
  color: var(--accent-ink);
  background: var(--accent);
  border: 2px solid var(--line);
  border-radius: 49% 51% 47% 53% / 55% 46% 54% 45%;
  box-shadow: 3px 4px 0 rgba(41, 51, 45, 0.2);
  font: 700 var(--fs-label)/1.2 var(--font-sans);
  letter-spacing: 0.015em;
}

.nt-button:hover {
  filter: saturate(1.08) brightness(1.02);
}

.nt-button:active {
  box-shadow: 1px 2px 0 rgba(41, 51, 45, 0.2);
  transform: translate(2px, 2px);
}

.nt-input {
  min-height: 48px;
  padding: 9px 14px;
  color: var(--text);
  background: var(--control-surface, rgba(255, 255, 255, 0.84));
  border: 2px solid var(--line);
  border-radius: 8px 12px 9px 11px / 11px 8px 12px 9px;
  box-shadow: inset 0 -3px 0 rgba(220, 236, 245, 0.75);
  font: 600 var(--fs-label)/1.25 var(--font-number);
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-button:focus-visible,
.nt-input:focus-visible,
.nt-controls input:focus-visible,
.nt-controls select:focus-visible,
.nt-controls textarea:focus-visible {
  outline: 4px solid color-mix(in srgb, var(--focus) 72%, white);
  outline-offset: 4px;
}

.nt-button:disabled,
.nt-input:disabled {
  opacity: 0.55;
  filter: grayscale(0.45);
}

.nt-error {
  color: var(--danger);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 650;
  line-height: 1.45;
}

.nt-title::selection,
.nt-body::selection,
.nt-lead::selection,
.nt-number::selection,
.nt-caption::selection,
.nt-note::selection {
  color: var(--accent-ink);
  background: rgba(243, 200, 63, 0.72);
}

@media (prefers-reduced-motion: reduce) {
  .nt-button,
  .nt-input {
    scroll-behavior: auto;
    transition: none;
  }
}
